var rows = msg.payload.sort(function(a,b){ return b.average_rating - a.average_rating; }).slice(0,10);
var html = '<table style="width:100%;border-collapse:collapse;font-size:13px">';
html += '<tr style="background:#1a1a2e;color:#e0e0e0"><th style="padding:6px;text-align:left">Title</th><th>Avg Rating</th><th>Votes</th></tr>';
rows.forEach(function(r,i){
    var bg = i%2===0?'#16213e':'#0f3460';
    html += '<tr style="background:'+bg+';color:#e0e0e0"><td style="padding:5px">'+r.title+'</td><td style="text-align:center">'+r.average_rating.toFixed(2)+'</td><td style="text-align:center">'+r.rating_count+'</td></tr>';
});
html += '</table>';
msg.payload = html;
return msg;

